    {
      status: 'issued',
      lines: [
        { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
      ],
    },
  ];
  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 0);
  assert.equal(result[0].base, 100000);
  assert.equal(result[0].vat, 0);
});

test('vatSummary calculates VAT on discounted amounts', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { qty: 10, unitPrice: 8500, discountPercent: 5, vatRate: 21 },
      ],
    },
  ];
  const result = vatSummary(invoices);
  const lineTotal = 10 * 8500;
  const discount = lineTotal * 0.05;
  const base = lineTotal - discount;
  const expectedVat = Math.round(base * 0.21);
  assert.equal(result[0].base, base);
  assert.equal(result[0].vat, expectedVat);
});

test('vatSummary with multiple discounted lines same rate', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [
        { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
        { qty: 100, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
      ],
    },
  ];
  const result = vatSummary(invoices);
  const base1 = 100000 - 10000;
  const base2 = 100000 - 5000;
  const vat1 = Math.round(base1 * 0.21);
  const vat2 = Math.round(base2 * 0.21);
  assert.equal(result[0].base, base1 + base2);
  assert.equal(result[0].vat, vat1 + vat2);
});

test('vatSummary does not mutate input', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
    },
  ];
  const originalInvoices = JSON.parse(JSON.stringify(invoices));
  vatSummary(invoices);
  assert.deepEqual(invoices, originalInvoices);
});

